const input = $input.first().json;

const consentToBoolean = (value) => {
  if (
    value === true ||
    value === 'true' ||
    value === '동의'
  ) {
    return true;
  }

  return false;
};

const cleanPhone = (value) => {
  if (!value) return null;
  return String(value).replace(/[^0-9]/g, '');
};

const toNumberOrNull = (value) => {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const number = Number(String(value).replace(/[^0-9]/g, ''));

  return Number.isNaN(number) ? null : number;
};

return [{
  json: {
    customer_id: `CUST-${Date.now()}`,

    customer_name: input.customer_name || null,

    phone: cleanPhone(input.phone),

    age: toNumberOrNull(input.age),

    current_device: input.current_device || null,

    current_plan: input.current_plan || null,

    contract_end_date: input.contract_end_date || null,

    device_use_months: toNumberOrNull(
      input.device_use_months
    ),

    usage_pattern: input.usage_pattern || null,

    consultation_goal: input.consultation_goal || null,

    interests: input.interests || null,

    preferred_brand: input.preferred_brand || null,

    target_monthly_budget: toNumberOrNull(
      input.target_monthly_budget
    ),

    privacy_consent: consentToBoolean(
      input.privacy_consent
    ),

    marketing_consent: consentToBoolean(
      input.marketing_consent
    ),

    recontact_consent: consentToBoolean(
      input.recontact_consent
    ),

    consent_at: new Date().toISOString()
  }
}];
